  { type: 'ok', payload: { nested: { value: 1 } } },
  { type: '', payload: {} },
]));
assert.deepEqual(feed.history('t'), []);
const input = { nested: { value: 1 } };
const committed = feed.publishBatch('t', [{ type: 'ok', payload: input }]);
input.nested.value = 2;
committed[0].payload.nested.value = 3;
const first = [], second = [];
feed.subscribe('t', 0, r => first.push(r));
feed.subscribe('t', 0, r => second.push(r));
feed.publishBatch('t', [{ type: 'next', payload: { nested: { value: 4 } } }]);
first[1].payload.nested.value = 9;
assert.equal(second[1].payload.nested.value, 4);
assert.equal(feed.history('t')[0].payload.nested.value, 1);
assert.equal(feed.history('t')[1].sequence, 2);

const router = createRouter({
  defaults: { enabled: true, timeout: 10, label: 'default', headers: { keep: 'yes', remove: 'me' } },
  routes: [
    { id: 'wild', pattern: '*', settings: { target: 'wild' } },
    { id: 'short', pattern: '/app/*', settings: { target: 'short' } },
    { id: 'long', pattern: '/app/admin/*', settings: { target: 'long' } },
    { id: 'exact', pattern: '/app/admin', settings: { target: 'exact' } },
  ],
});
assert.equal(router.resolve('a', '/app/admin').route, 'exact');
assert.equal(router.resolve('a', '/app/admin/x').route, 'long');
assert.equal(router.resolve('a', '/apple').route, 'wild');
router.setTenant('a', { enabled: false, timeout: 0, label: '', headers: { remove: null, keep: '' } });
const resolved = router.resolve('a', '/app/x');
assert.equal(resolved.enabled, false);
assert.equal(resolved.timeout, 0);
assert.equal(resolved.label, '');
assert.deepEqual(resolved.headers, { keep: '' });
router.setTenant('a', { enabled: true });
assert.equal(router.resolve('a', '/app/x').enabled, true);
assert.equal(router.resolve('b', '/app/x').enabled, true);

let now = 50;
const store = new ExpiringStore({ now: () => now });
const cache = new TenantCache(store);
let loads = 0;
await cache.getOrLoad('a:b', 'c', async () => { loads++; return false; }, 10);
assert.equal(await cache.getOrLoad('a', 'b:c', async () => { loads++; return 0; }, 10), 0);
assert.equal(loads, 2);
assert.equal(await cache.getOrLoad('a:b', 'c', async () => { loads++; return 1; }, 10), false);
now = 60;
